import React,{useEffect,useState} from 'react';
import {Ionicons} from '@expo/vector-icons';
import { Alert, Image, Pressable, ScrollView, StyleSheet, View } from 'react-native';
import { Banner, BellButton, Collapse, ListLine, MoreToggle, Button, Card, Chip, Empty, EquipmentImage, Field, formatDate, formatDay, formatWhen, formatTime, Lead, LinkRow, List, Pill, Screen, ScanSheet, Section, Segmented, SelectField, CheckRow, Sheet, TimeRangeField, ClockField, DateField, Title, confirm, statusLabel, statusTone, Text } from '../design/components';
import {colors as c} from '../design/tokens';
import {useApp} from '../state/AppProvider';
const hasText=v=>!!String(v||'').trim();
export function AdminDashboard({navigation}){const{state,policy}=useApp();const broken=state.bookings.filter(b=>b.brokenReported&&policy.HELD.includes(b.status));const unanswered=[...state.inquiries.map(x=>({...x,kind:'문의',type:'inquiries'})),...state.purchases.map(x=>({...x,kind:'구매 요청',type:'purchases'}))].filter(x=>!x.response);const who=id=>state.users.find(u=>u.id===id)?.name||'탈퇴 회원';const pending=state.users.filter(u=>u.approval==='pending');const pickup=state.bookings.filter(b=>b.status==='RESERVED');const modelName=b=>state.models.find(m=>m.id===b.modelId)?.name;const[showAll,setShowAll]=useState(false);
  const items=[
    ...broken.map(b=>({key:'broken-'+b.id,title:`${modelName(b)} · 파손 신고`,subtitle:`${who(b.userId)} · ${b.brokenNote||'내용 없음'}`,tone:'danger',go:()=>navigation.navigate('AdminHandoff',{bookingId:b.id})})),
        ...pickup.map(b=>({key:'pick-'+b.id,title:`${modelName(b)} · 예약자 수령 대기`,subtitle:`${who(b.userId)} · ${formatWhen(b,'start')}`,go:()=>navigation.navigate('AdminHandoff',{bookingId:b.id})})),
    ...pending.map(u=>({key:'user-'+u.id,title:`${u.name} · 학생증 승인`,subtitle:u.studentNumber,go:()=>navigation.navigate('AdminStudentDetail',{userId:u.id})})),
    ...unanswered.map(x=>({key:'req-'+x.id,title:x.title,subtitle:`${x.kind} 답변 대기 · ${who(x.userId)}`,go:()=>navigation.navigate('AdminRequests',{type:x.type})})),
  ];return <Screen><Title subtitle="모든 장소의 운영 현황" right={<BellButton onPress={()=>navigation.navigate('Notifications')}/>}>관리자 홈</Title><View style={s.actionRow}>{[['현장 대여 처리','예약 없이 온 학생에게 바로 빌려줍니다','bag-check-outline',()=>navigation.navigate('AdminWalkIn')],['반납 처리','기기를 찍거나 고유 번호로 찾습니다','arrow-undo-outline',()=>navigation.navigate('AdminReturnLookup',{mode:'return'})]].map(([title,text,icon,go])=><Pressable key={title} accessibilityRole="button" accessibilityLabel={title} onPress={go} android_ripple={{color:'rgba(255,255,255,0.24)'}} style={({pressed})=>[s.action,pressed&&s.actionPressed]}><View style={s.actionIcon}><Ionicons name={icon} size={22} color="#fff"/></View><View style={s.actionBody}><Text style={s.actionTitle}>{title}</Text><Text style={s.actionText}>{text}</Text></View></Pressable>)}</View><View style={s.statusCard}>{[['학생증 승인 대기',pending.length,'AdminStudents',{approval:'pending'}],['예약자 대여 처리',pickup.length,'AdminRentals',{status:'RESERVED'}],['대여 중',state.bookings.filter(b=>b.status==='RENTING').length,'AdminRentals',{status:'RENTING'}]].map(([label,n,route,params],k)=><Pressable key={label} accessibilityRole="button" accessibilityLabel={`${label} ${n}건 보기`} onPress={()=>navigation.navigate(route,{...params,at:Date.now()})} android_ripple={{color:c.softPress}} style={({pressed})=>[s.statusCell,k>0&&s.statusLine,pressed&&s.statusPressed]}><Text style={[s.statusNumber,!n&&s.statusZero]}>{n}</Text><Text style={s.statusLabel}>{label}</Text></Pressable>)}</View><Section title="우선 처리"><Lead>급한 순서로 3건을 먼저 보여 줍니다.</Lead><List>{items.slice(0,3).map(x=><LinkRow key={x.key} title={x.title} subtitle={x.subtitle} tone={x.tone} onPress={x.go}/>)}{items.length>3?<Collapse key="more" noDivider open={showAll}>{items.slice(3).map(x=><React.Fragment key={x.key}><ListLine/><LinkRow title={x.title} subtitle={x.subtitle} tone={x.tone} onPress={x.go}/></React.Fragment>)}</Collapse>:null}{!items.length?<Empty title="처리 대기 항목이 없습니다"/>:null}</List>{items.length>3?<MoreToggle open={showAll} count={items.length-3} onPress={()=>setShowAll(v=>!v)}/>:null}</Section><Section title="운영 도구"><List>{[['알림 관리','AdminNotices'],['문의 답변','AdminRequests',unanswered.length?`답변 대기 ${unanswered.length}건`:null],['운영일·시간 변경','AdminOperations'],['관리 기록','AdminAudit'],['이용 통계','AdminStats']].map(([label,route,sub])=><LinkRow key={route} title={label} subtitle={sub||undefined} onPress={()=>navigation.navigate(route)}/>)}</List></Section></Screen>}
const ADMIN_STATUS={...statusLabel,RESERVED:'예약자 수령 대기',WAITING:'앞 사용자 반납 대기'};
export function AdminRentalsScreen({navigation,route}){const{state}=useApp();const[q,setQ]=useState(''),[status,setStatus]=useState(route?.params?.status||'전체');useEffect(()=>{if(route?.params?.status)setStatus(route.params.status)},[route?.params?.at]);const list=state.bookings.filter(b=>status==='전체'||b.status===status).filter(b=>{const u=state.users.find(x=>x.id===b.userId),m=state.models.find(x=>x.id===b.modelId);return `${u?.name||''} ${u?.studentNumber||''} ${m?.name||''} ${b.unitId||''}`.toLowerCase().includes(q.toLowerCase())}).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return <Screen><Title subtitle={`${status==='전체'?'전체':ADMIN_STATUS[status]} ${list.length}건`}>대여 관리</Title><Field label="학생, 모델, 기기 고유 번호 검색" value={q} onChangeText={setQ}/><View style={s.chips}>{['전체','RESERVED','RENTING','WAITING','NO_SHOW','RETURNED'].map(x=><Chip key={x} label={ADMIN_STATUS[x]||x} selected={status===x} onPress={()=>setStatus(x)}/>)}</View><View style={s.rowList}>{list.length?list.map(b=><Card key={b.id} style={s.card} onPress={()=>navigation.navigate('RentalDetail',{bookingId:b.id})}><View style={s.row}><Text style={s.heading}>{state.users.find(u=>u.id===b.userId)?.name||'탈퇴 회원'}</Text><Pill text={ADMIN_STATUS[b.status]} tone={statusTone[b.status]}/></View><Text style={s.meta} numberOfLines={2}>{state.models.find(m=>m.id===b.modelId)?.name} · {formatWhen(b,'start')}</Text><Button title={['RESERVED','WAITING'].includes(b.status)?'수령 처리':b.status==='RENTING'?'반납 처리':b.status==='NO_SHOW'?'미수령 정정':'상세 보기'} kind="secondary" compact onPress={()=>navigation.navigate(['RESERVED','WAITING','RENTING'].includes(b.status)?'AdminHandoff':b.status==='NO_SHOW'?'AdminCorrection':'RentalDetail',{bookingId:b.id})}/></Card>):<Empty title="기록이 없습니다"/>}</View></Screen>}
export function AdminWalkIn({navigation}){const{state,currentUser,run,policy}=useApp();const[number,setNumber]=useState(''),[studentId,setStudentId]=useState(null),[modelId,setModelId]=useState(null),[unitId,setUnitId]=useState(''),[end,setEnd]=useState(null),[mail,setMail]=useState(false),[scanning,setScanning]=useState(false);
  const student=state.users.find(u=>u.id===studentId);
  const held=m=>state.bookings.filter(b=>b.modelId===m.id&&policy.HELD.includes(b.status)).map(b=>b.unitId);
  const freeUnits=m=>m?m.units.filter(u=>u.condition==='NORMAL'&&!held(m).includes(u.id)):[];
  const models=state.models.filter(m=>!m.archived&&freeUnits(m).length&&policy.walkInEndOptions(state,m).length);
  const model=state.models.find(m=>m.id===modelId);
  const ends=model?policy.walkInEndOptions(state,model):[];
  const reservations=student?state.bookings.filter(b=>b.userId===student.id&&['RESERVED','WAITING'].includes(b.status)):[];
  const overdue=student?state.bookings.some(b=>b.userId===student.id&&policy.HELD.includes(b.status)&&new Date(b.end)<=new Date()):false;
  const findStudent=()=>{const u=state.users.find(x=>x.role==='student'&&x.studentNumber===number.trim());if(!u){Alert.alert('학생을 찾을 수 없습니다','학번을 확인해 주세요.');return;}setStudentId(u.id)};
  const pickModel=id=>{setModelId(id);setUnitId('');setEnd(null);setMail(false)};
  const fromCode=v=>{const code=String(v).trim();const m=state.models.find(x=>!x.archived&&x.units.some(u=>u.id===code));setScanning(false);if(!m){Alert.alert('기기를 찾을 수 없습니다','읽은 코드와 일치하는 기기 고유 번호가 없습니다.');return;}if(!freeUnits(m).some(u=>u.id===code)){Alert.alert('빌려줄 수 없는 기기입니다','대여 중이거나 점검 중인 기기입니다.');return;}setModelId(m.id);setUnitId(code);setEnd(null)};
  const label=iso=>{const d=new Date(iso),today=new Date().toDateString()===d.toDateString();return today?`오늘 ${formatTime(iso)}까지`:`${formatDate(iso)}까지`};
  const start=()=>{try{const next=policy.walkIn(state,student?.id,modelId,unitId,end,currentUser.id,new Date(),mail);run(()=>next);Alert.alert('현장 대여 시작',`${student.name} 학생에게 ${model.name} ${unitId}을(를) 빌려주었습니다.`,[{text:'확인',onPress:()=>navigation.goBack()}]);}catch(e){Alert.alert('빌려줄 수 없습니다',e.message)}};
  const ready=student&&model&&unitId&&end&&(model.rentalType!=='장기'||mail);
  return <Screen>
    <Lead>예약 없이 온 학생에게 바로 빌려줍니다. 예약자가 잡아둔 시간은 비워둔 채로 반납 기한이 계산됩니다.</Lead>
    <ScanSheet visible={scanning} onClose={()=>setScanning(false)} onScanned={fromCode} title="대여 기기 스캔"/>
    <Section title="1. 학생">
      <Field label="학번" value={number} onChangeText={v=>{setNumber(v);setStudentId(null)}} keyboardType="number-pad" placeholder="학생증의 학번" disabled={!models.length}/>
      {!student?<Button title="학생 찾기" kind="secondary" disabled={!models.length} onPress={findStudent}/>:<Card style={s.card}><View style={s.row}><Text style={s.heading}>{student.name}</Text><Pill text={student.approval!=='approved'?'학생증 승인 대기':policy.suspended(state,student.id)?'이용 정지':overdue?'연체 중':'대여 가능'} tone={student.approval!=='approved'||policy.suspended(state,student.id)||overdue?'danger':'good'}/></View><Text style={s.meta}>{student.studentNumber} · 유효 경고 {policy.activeWarnings(state,student.id).length}회 · 학생증은 창구에서 확인해 주세요</Text></Card>}
      {reservations.length?<Banner tone="warn" text={`이 학생은 예약이 ${reservations.length}건 있습니다. 예약한 기자재라면 예약자 대여로 처리해 주세요.`}/>:null}
      {reservations.map(b=><Button key={b.id} title={`${state.models.find(m=>m.id===b.modelId)?.name} · 예약자 대여 처리`} kind="secondary" compact onPress={()=>navigation.navigate('AdminHandoff',{bookingId:b.id})}/>)}
    </Section>
    <Section title="2. 기기">
      {!models.length?<Banner tone="warn" text={(()=>{const now=new Date(),h=state.holidays.find(x=>x.date===policy.dateKey(now));if(h)return `오늘은 쉬는 날(${h.reason})이라 현장 대여를 할 수 없습니다.`;if(policy.closedDay(state,now))return '오늘은 주말이라 현장 대여를 할 수 없습니다.';const hm=now.getHours()*60+now.getMinutes();if(hm<9*60||hm>=20*60)return '지금은 운영 시간(09:00~20:00)이 아니라 현장 대여를 할 수 없습니다.';return '지금 빌려줄 수 있는 기기가 없습니다. 모든 기기가 나가 있거나 곧 예약이 있습니다.';})()}/>:null}
      <Button title="QR·바코드 찍기" kind="secondary" icon="qr-code-outline" compact disabled={!models.length} onPress={()=>setScanning(true)}/>
      <SelectField label="모델" value={modelId} onChange={pickModel} disabled={!models.length} placeholder={`지금 빌려줄 수 있는 모델 ${models.length}개`} options={models.map(m=>({value:m.id,model:m,label:`${m.name} · 남은 기기 ${freeUnits(m).length}대`,sub:m.category,title:m.name,meta:`남은 기기 ${freeUnits(m).length}대`}))} unknown={()=>model?.name||''}/>
      <SelectField label="기기" value={unitId} onChange={v=>{setUnitId(v)}} disabled={!model} placeholder={model?`남은 기기 ${freeUnits(model).length}대`:'모델을 먼저 고르세요'} options={model?freeUnits(model).map(u=>({value:u.id,label:`${u.id} · ${u.name}`,model,sub:`기기 번호 ${u.id}`,title:u.name})):[]}/>
    </Section>
    <Section title="3. 반납 기한">
      {!model?<SelectField label="반납 기한" value={null} onChange={()=>{}} disabled placeholder="모델을 먼저 고르세요" options={[]}/>:ends.length?<SelectField label="반납 기한" value={end} onChange={setEnd} placeholder="고르세요" options={ends.map(o=>({value:o.end,label:label(o.end)}))}/>:<Banner tone="warn" text="지금은 이 모델을 빌려줄 수 없습니다. 운영 시간 밖이거나 쉬는 날(주말·공휴일)이거나, 곧 예약이 있습니다."/>}
      {model&&model.rentalType==='장기'?<CheckRow label="지도교수 메일 현장 확인" checked={mail} onPress={()=>setMail(!mail)}/>:null}
    </Section>
    <Button title="현장 대여 시작" disabled={!ready} onPress={start}/>
  </Screen>}
export function AdminHandoffScreen({route,navigation}){const{state,currentUser,run,policy}=useApp();const b=state.bookings.find(x=>x.id===route.params?.bookingId);const scanned=route.params?.code||'';const[code,setCode]=useState(scanned),[condition,setCondition]=useState('NORMAL'),[mail,setMail]=useState(false),[scanning,setScanning]=useState(false);useEffect(()=>{if(b)navigation.setOptions({title:policy.HELD.includes(b.status)?'반납 처리':'수령 처리'})},[navigation,b?.status]);if(!b)return <Screen><Empty title="예약이 없습니다"/></Screen>;const model=state.models.find(m=>m.id===b.modelId);const returning=policy.HELD.includes(b.status);const submit=()=>{try{const next=returning?policy.returnUnit(state,b.id,code.trim(),condition,currentUser.id):policy.pickup(state,b.id,code.trim(),currentUser.id,new Date(),mail);run(()=>next);Alert.alert('처리 완료',returning?'반납 및 기기 상태가 반영되었습니다.':'대여가 시작되었습니다.',[{text:'확인',onPress:()=>navigation.goBack()}]);}catch(e){Alert.alert('처리할 수 없습니다',e.message)}};return <Screen><Title subtitle={ADMIN_STATUS[b.status]}>{model.name}</Title><Banner text={returning&&scanned?'찾을 때 쓴 기기 고유 번호가 들어 있습니다.':'기기에 붙은 QR·바코드를 찍거나 고유 번호를 입력해 주세요.'}/><ScanSheet visible={scanning} onClose={()=>setScanning(false)} onScanned={v=>{setCode(v);setScanning(false)}} title={returning?'반납 기기 스캔':'수령 기기 스캔'}/><Card><Text style={s.heading}>신청자 {state.users.find(u=>u.id===b.userId)?.name}</Text><Text style={s.meta}>{formatWhen(b,'start')} → {formatWhen(b,'end')}</Text><Text style={s.meta}>예약 기기: {b.unitId||'수령 시 배정'}</Text></Card><Field label="기기 고유 번호" value={code} onChangeText={setCode} disabled={returning&&!!scanned} placeholder={returning?b.unitId:model.units[0]?.id}/>{returning&&scanned?null:<Button title="QR·바코드 찍기" kind="secondary" icon="qr-code-outline" compact onPress={()=>setScanning(true)}/>}{!returning?<SelectField label="배정할 기기" value={code} onChange={setCode} placeholder={`목록에서 고르기 (${model.units.filter(u=>u.condition==='NORMAL').length}대)`} options={model.units.filter(u=>u.condition==='NORMAL').map(u=>({value:u.id,label:`${u.id} · ${u.name}`,model,sub:`기기 번호 ${u.id}`,title:u.name}))} unknown={v=>`${v} · 배정 가능 목록에 없는 번호`}/>:<Section title="반납 기기 상태"><View style={s.row}><Button title="정상" kind={condition==='NORMAL'?'primary':'secondary'} style={s.half} onPress={()=>setCondition('NORMAL')}/><Button title="훼손" kind={condition==='DAMAGED'?'danger':'secondary'} style={s.half} onPress={()=>setCondition('DAMAGED')}/></View>{b.brokenReported?<Banner text={`학생이 대여 중 이상을 신고했습니다. 신고 내용: ${b.brokenNote||'내용 없음'}`} tone="warn"/>:null}</Section>}{model.rentalType==='장기'&&!returning?<CheckRow label="지도교수 메일 현장 확인" checked={mail} onPress={()=>setMail(!mail)}/>:null}<Button title={returning?'반납 완료 처리':'수령 완료 처리'} onPress={submit}/></Screen>}
export function AdminCorrectionScreen({route,navigation}){const{state,currentUser,run,policy}=useApp();const b=state.bookings.find(x=>x.id===route.params?.bookingId);const[unit,setUnit]=useState(null),[time,setTime]=useState(null),[mail,setMail]=useState(false);if(!b)return <Screen><Empty title="기록이 없습니다"/></Screen>;const model=state.models.find(m=>m.id===b.modelId);const student=state.users.find(u=>u.id===b.userId);
  const held=model.units.filter(u=>state.bookings.some(x=>x.id!==b.id&&x.modelId===model.id&&x.unitId===u.id&&policy.HELD.includes(x.status))).map(u=>u.id);const units=model.units.filter(u=>u.condition==='NORMAL'&&!held.includes(u.id));
  const open=policy.openFor(state,model,b.start).getTime(),last=Math.min(policy.closeFor(state,model,b.start).getTime(),new Date(b.end).getTime()-1,Date.now()); // 지금보다 뒤의 시각은 고를 수 없다 // 예약한 날 운영 시간 안에서 고른다(조기 수령·오후 수령 포함)
  const apply=()=>{if(!time||!unit){Alert.alert('실제 수령 시각과 기기 고유 번호를 골라 주세요');return;}try{const next=policy.correctNoShow(state,b.id,unit,currentUser.id,new Date(time),mail);run(()=>next);navigation.goBack();}catch(e){Alert.alert('정정할 수 없습니다',e.message)}};
  return <Screen><Card style={s.card}><View style={s.row}><Text style={s.heading}>{student?.name||'탈퇴 회원'}</Text><Pill text="미수령" tone="danger"/></View><Text style={s.meta} numberOfLines={2}>{model.name} · {formatWhen(b,'start')}</Text></Card><Banner text="학생이 실제로 기기를 받아 간 게 확인될 때만 정정하세요. 이 예약의 미수령 경고가 철회되고 관리 기록에 남습니다." tone="warn"/><ClockField label={`실제 수령 시각 (${formatDay(b.start)})`} value={time} onChange={setTime} min={open} max={last} placeholder="운영 시간 안에서 5분 단위"/><SelectField label="기기 고유 번호" value={unit} onChange={setUnit} placeholder={`고를 수 있는 기기 ${units.length}대`} options={units.map(u=>({value:u.id,label:`${u.id} · ${u.name}`,model,sub:`기기 번호 ${u.id}`,title:u.name}))}/>{model.rentalType==='장기'?<Button title={mail?'교수 메일 확인됨':'교수 메일 현장 확인'} kind="secondary" onPress={()=>setMail(!mail)}/>:null}<Button title="정정 저장" disabled={!time||!unit} onPress={apply}/></Screen>}
export function AdminStudentsScreen({navigation,route}){const{state,policy}=useApp();const[approval,setApproval]=useState(route?.params?.approval||'all');useEffect(()=>{if(route?.params?.approval)setApproval(route.params.approval)},[route?.params?.at]);const labels={all:'전체',pending:'학생증 승인 대기',approved:'승인',rejected:'반려',warned:'경고',suspended:'정지'};
  const info=u=>{const stop=policy.suspended(state,u.id),warns=policy.activeWarnings(state,u.id).length;return{stop,warns}};
  const match=u=>{const{stop,warns}=info(u);return approval==='all'||(approval==='suspended'?stop:approval==='warned'?!stop&&warns>0:u.approval===approval)};
  const pills=u=>{const{stop,warns}=info(u);const list=[{text:labels[u.approval]||u.approval,tone:u.approval==='approved'?'good':u.approval==='rejected'?'orange':'neutral'}];if(stop)list.push({text:'이용 정지',tone:'danger'});else if(warns)list.push({text:`경고 ${warns}회`,tone:'warn'});return list};
  const sub=u=>{const{stop,warns}=info(u);if(stop)return u.suspendedUntilReturn?`경고 ${warns}회 · 기기 반납 전까지 정지`:`경고 ${warns}회 · ${formatDay(u.suspendedUntil)}까지 정지`;if(warns){const last=[...policy.activeWarnings(state,u.id)].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];return `${u.studentNumber} · 최근 경고 ${formatDay(last.createdAt)}`}return `${u.studentNumber} · ${u.email}`};
  const list=state.users.filter(u=>u.role==='student'&&match(u));
  return <Screen><Title subtitle={`${labels[approval]} ${list.length}명`}>학생 관리</Title><View style={s.chips}>{Object.entries(labels).map(([k,v])=><Chip key={k} label={v} selected={approval===k} onPress={()=>setApproval(k)}/>)}</View><View style={s.rowList}>{list.length?list.map(u=><Card key={u.id} style={s.card} onPress={()=>navigation.navigate('AdminStudentDetail',{userId:u.id})}><View style={s.row}><Text style={s.heading}>{u.name}</Text><View style={s.pills}>{pills(u).map(p=><Pill key={p.text} text={p.text} tone={p.tone}/>)}</View></View><Text style={s.meta} numberOfLines={2}>{sub(u)}</Text></Card>):<Empty title="해당하는 학생이 없습니다"/>}</View></Screen>}
function StudentIdPhoto({user}){if(/^(file|ph|content|https?|blob|data):/.test(user.studentIdPhoto||''))return <View style={[s.idImage,{backgroundColor:'#fff'}]}><Image source={{uri:user.studentIdPhoto}} resizeMode="contain" accessibilityLabel={`${user.name} 학생증 사진`} style={s.idFill}/></View>;const[width,setWidth]=useState(0);/* 예시 학생(사진 대신 표시): 피그마 Student ID Card 종류=헤이영처럼 헤이영 화면에서 이름·학번·얼굴 부분을 카드 틀로 자른 모습. 원본 336 기준 좌표의 파란 영역 위부터 얼굴 아래까지(높이 230) */const H=width/(900/560),k=H/230,W=336*k;return <View onLayout={e=>setWidth(e.nativeEvent.layout.width)} accessible accessibilityLabel={`${user.name} 학생증 사진`} style={[s.idImage,{backgroundColor:'#fff'}]}>{width?<View style={[s.hyCrop,{left:(width-W)/2,width:W}]}><View style={[s.hyBlue,{height:196*k}]}/><View style={[s.hyHandle,{top:12*k,left:150*k,width:36*k,height:4*k,borderRadius:2*k}]}/><Text style={[s.hyName,{top:42*k,fontSize:19*k,lineHeight:23*k}]}>{user.name} ({user.studentNumber})</Text><Text style={[s.hyMeta,{top:74*k,fontSize:13*k,lineHeight:16*k}]}>컴퓨터공학부, 재학 2학년</Text><View style={[s.hyFace,{top:122*k,left:116*k,width:104*k,height:104*k,borderRadius:52*k,borderWidth:4*k}]}><View style={[s.hyFacePart,{left:29*k,top:18*k,width:38*k,height:38*k,borderRadius:19*k}]}/><View style={[s.hyFacePart,{left:10*k,top:62*k,width:76*k,height:64*k,borderRadius:38*k}]}/></View></View>:null}</View>;}
export function AdminStudentDetail({route,navigation}){const{state,currentUser,run,policy}=useApp();const u=state.users.find(x=>x.id===route.params?.userId);const[name,setName]=useState(u?.name||''),[number,setNumber]=useState(u?.studentNumber||''),[reason,setReason]=useState('');if(!u)return <Screen><Empty title="학생을 찾을 수 없습니다"/></Screen>;const update=(approval)=>{if(approval==='rejected'&&!reason.trim()){Alert.alert('반려 사유를 입력해 주세요');return;}run(s=>{const n=policy.clone(s),target=n.users.find(x=>x.id===u.id);target.approval=approval;target.rejectReason=approval==='rejected'?reason.trim():'';target.studentIdPhoto=null;policy.notify(n,u.id,approval==='approved'?'계정 승인':'학생증 재제출 필요',target.rejectReason||'이제 대여를 신청할 수 있습니다.','ACCOUNT');return n});};const save=()=>{if(!name.trim()||!number.trim()||state.users.some(x=>x.id!==u.id&&x.studentNumber===number.trim())){Alert.alert('이름 또는 학번을 확인해 주세요');return;}run(s=>({...s,users:s.users.map(x=>x.id===u.id?{...x,name:name.trim(),studentNumber:number.trim()}:x)}));Alert.alert('저장되었습니다')};const warnings=policy.activeWarnings(state,u.id);return <Screen><Title>{u.name}</Title><Banner text={`${u.email} · ${u.approval} · 학생증 ${u.studentIdPhoto?'제출됨':'보관 없음'}`}/>{u.studentIdPhoto?<Section title="제출한 학생증"><Card style={s.idCard}><StudentIdPhoto user={u}/></Card></Section>:null}{u.approval==='pending'?<Section title="학생증 심사"><Button title="승인" onPress={()=>update('approved')}/><Field label="반려 사유" value={reason} onChangeText={setReason} multiline/><Button title="사유와 함께 반려" kind="danger" onPress={()=>update('rejected')}/></Section>:null}<Section title="학생 정보 수정"><Field label="이름" value={name} onChangeText={setName}/><Field label="학번" value={number} onChangeText={setNumber}/><Button title="정보 저장" kind="secondary" onPress={save}/></Section><Section title={`유효 경고 ${warnings.length}회`}>{u.suspendedUntilReturn?<Banner tone="danger" text="보유 기기를 모두 반납하면 6개월 정지가 시작됩니다."/>:u.suspendedUntil?<Banner tone="danger" text={`정지 해제 예정: ${formatDate(u.suspendedUntil)}`}/>:null}<View style={s.rowList}>{warnings.length?warnings.map(w=><Card key={w.id} style={s.card}><Text style={s.heading}>{w.kind} · {state.models.find(m=>m.id===state.bookings.find(b=>b.id===w.bookingId)?.modelId)?.name||'기존 기록'}</Text><Text style={s.meta}>{formatDate(w.createdAt)}{w.expiresAt?` · 만료 ${formatDate(w.expiresAt)}`:''}</Text><Button title="경고 철회" kind="secondary" onPress={()=>confirm('경고 철회','이 경고만 철회합니다.',()=>run(x=>policy.revokeWarning(x,w.id,currentUser.id,'관리자 검토 후 철회')))}/></Card>):<Empty title="경고가 없습니다"/>}</View></Section></Screen>}
export function AdminEquipmentScreen({navigation}){const{state}=useApp();const[q,setQ]=useState('');return <Screen><Title subtitle={`${state.models.length}개 모델 · 학교 자료 기준 모델`}>기자재 관리</Title><Button title="새 모델 추가" onPress={()=>navigation.navigate('AdminModelEdit',{})}/><Field label="모델 검색" value={q} onChangeText={setQ}/><View style={s.modelList}>{state.models.filter(m=>`${m.name} ${m.category}`.toLowerCase().includes(q.toLowerCase())).map(m=><Card key={m.id} style={s.modelRow} onPress={()=>navigation.navigate('AdminModelEdit',{modelId:m.id})}><EquipmentImage model={m} style={s.modelImage}/><View style={s.modelText}><Text style={s.modelCategory}>{m.category}</Text><Text style={s.modelName} numberOfLines={2}>{m.name}</Text><Text style={s.modelMeta}>정상 {m.units.filter(u=>u.condition==='NORMAL').length}/{m.units.length}대 · {m.source==='demo'?'직접 등록':'학교 자료'}</Text></View><Ionicons name="chevron-forward" size={18} color={c.muted}/></Card>)}</View></Screen>}
export function AdminModelEdit({route,navigation}){const{state,currentUser,run,policy}=useApp();const m=state.models.find(x=>x.id===route.params?.modelId);const[name,setName]=useState(m?.name||''),[category,setCategory]=useState(m?.category||''),[maker,setMaker]=useState(m?.manufacturer||''),[purpose,setPurpose]=useState(m?.purpose||''),[location,setLocation]=useState(m?.location||''),[contact,setContact]=useState(m?.contact||''),[time,setTime]=useState(m?.operatingTime||'09:00~20:00'),[type,setType]=useState(m?.rentalType||'일반'),[multi,setMulti]=useState(!!m?.multiDay),[carry,setCarry]=useState(!!m?.carryOut),[unitCode,setUnitCode]=useState(''),[unitNames,setUnitNames]=useState({});const save=()=>{if(!name.trim()||!category.trim()||!/^\d\d:\d\d~\d\d:\d\d$/.test(time)||time.split('~')[0]>=time.split('~')[1]){Alert.alert('모델명, 분류와 운영 시간을 확인해 주세요');return;}run(s=>{let n=policy.clone(s);const data={name:name.trim(),category:category.trim(),manufacturer:maker.trim(),purpose:purpose.trim(),location:location.trim(),contact:contact.trim(),operatingTime:time,rentalType:type,multiDay:multi,carryOut:carry};if(m){Object.assign(n.models.find(x=>x.id===m.id),data);if(m.operatingTime!==time){for(const b of n.bookings.filter(b=>b.modelId===m.id&&['RESERVED','WAITING'].includes(b.status)))n=policy.invalidateBookings(n,m.id,b.start,'운영 시간 변경',currentUser.id);}policy.audit(n,'MODEL_EDIT',m.id,currentUser.id)}else{const id=policy.id('model');n.models.push({...data,id,number:'추가',source:'demo',purchaseYear:'',intervalMinutes:60,quantity:0,units:[],guide:'관리자가 추가한 모델입니다.',imageId:null});policy.audit(n,'MODEL_ADD',id,currentUser.id)}return n});navigation.goBack()};const saveUnitName=unit=>{const value=(unitNames[unit.id]||'').trim();if(!value){Alert.alert('기기명을 입력해 주세요');return;}run(s=>{const n=policy.clone(s);n.models.find(x=>x.id===m.id).units.find(x=>x.id===unit.id).name=value;policy.audit(n,'UNIT_EDIT',`${m.id}/${unit.id}`,currentUser.id);return n})};const updateCondition=(unit,status)=>run(s=>{const n=policy.clone(s),target=n.models.find(x=>x.id===m.id).units.find(x=>x.id===unit.id);target.condition=status;policy.audit(n,'UNIT_CONDITION',`${m.id}/${unit.id}/${status}`,currentUser.id);return policy.reduceCapacity(n,m.id,currentUser.id)});const deleteUnit=unit=>{if(state.bookings.some(b=>b.modelId===m.id&&b.unitId===unit.id&&policy.HELD.includes(b.status))){Alert.alert('삭제할 수 없습니다','대여 중인 기기입니다.');return;}confirm('기기 삭제',unit.id,()=>run(s=>{const n=policy.clone(s),model=n.models.find(x=>x.id===m.id);model.units=model.units.filter(x=>x.id!==unit.id);model.quantity=model.units.length;return policy.reduceCapacity(n,m.id,currentUser.id)}))};const addUnit=()=>{if(!unitCode.trim()||state.models.some(model=>model.units.some(u=>u.id===unitCode.trim()))){Alert.alert('고유한 기기 번호를 입력해 주세요');return;}run(s=>{const n=policy.clone(s),model=n.models.find(x=>x.id===m.id);model.units.push({id:unitCode.trim(),name:`${model.name} ${model.units.length+1}`,condition:'NORMAL'});model.quantity=model.units.length;return n});setUnitCode('')};const deleteModel=()=>{if(state.bookings.some(b=>b.modelId===m.id&&policy.HELD.includes(b.status))){Alert.alert('삭제할 수 없습니다','대여 중인 기기가 있습니다.');return;}confirm('모델 운영 종료','기존 기록은 보관하고 미래 예약은 경고 없이 취소합니다.',()=>{run(s=>policy.archiveModel(s,m.id,currentUser.id));navigation.goBack()})};return <Screen><Title>{m?'모델 수정':'모델 추가'}</Title><Field label="모델명" value={name} onChangeText={setName}/><Field label="분류" value={category} onChangeText={setCategory}/><Field label="제조사" value={maker} onChangeText={setMaker}/><Field label="활용 목적" value={purpose} onChangeText={setPurpose} multiline/><Field label="대여 장소" value={location} onChangeText={setLocation}/><Field label="연락처" value={contact} onChangeText={setContact}/><TimeRangeField label="운영 시간" value={time} onChange={setTime}/><Button title={`대여 방식: ${type}`} kind="secondary" onPress={()=>setType(type==='일반'?'장기':'일반')}/><Button title={`여러 날 대여: ${multi?'예':'아니오'}`} kind="secondary" onPress={()=>setMulti(!multi)}/><Button title={`반출: ${carry?'가능':'불가'}`} kind="secondary" onPress={()=>setCarry(!carry)}/><Button title="모델 저장" onPress={save}/>{m?<Section title={`개별 기기 ${m.units.length}대`}><Field label="새 기기 번호" value={unitCode} onChangeText={setUnitCode}/><Button title="기기 추가" kind="secondary" onPress={addUnit}/><View style={s.rowList}>{m.units.map(u=><Card key={u.id} style={s.card}><Text style={s.heading}>{u.name}</Text><Text style={s.meta}>{u.id} · {u.condition}</Text><Field label="기기명 수정" value={unitNames[u.id]??u.name} onChangeText={v=>setUnitNames(x=>({...x,[u.id]:v}))}/>{unitNames[u.id]&&unitNames[u.id]!==u.name?<Button title="기기명 저장" kind="secondary" onPress={()=>saveUnitName(u)}/>:null}<View style={s.row}>{['NORMAL','INSPECTION','DAMAGED'].map(x=><Button key={x} title={x==='NORMAL'?'정상':x==='INSPECTION'?'점검':'훼손'} kind={u.condition===x?'primary':'secondary'} compact style={s.third} onPress={()=>updateCondition(u,x)}/>)}</View><Button title="기기 삭제" kind="quiet" onPress={()=>deleteUnit(u)}/></Card>)}</View><Button title="모델 운영 종료" kind="danger" onPress={deleteModel}/></Section>:null}</Screen>}
export function AdminNoticesScreen({navigation}){const{state}=useApp();return <Screen><Button title="새 알림 작성" onPress={()=>navigation.navigate('AdminNoticeEdit',{})}/><View style={s.rowList}>{state.notices.map(n=><Card key={n.id} style={s.card} onPress={()=>navigation.navigate('AdminNoticeEdit',{id:n.id})}><Text style={s.heading}>{n.title}</Text><Text style={s.meta}>{formatDate(n.updatedAt)}</Text></Card>)}</View></Screen>}
export function AdminNoticeEdit({route,navigation}){const{state,run,policy,currentUser}=useApp();const n=state.notices.find(x=>x.id===route.params?.id);useEffect(()=>{navigation.setOptions({title:n?'알림 수정':'새 알림'})},[navigation,n]);const[title,setTitle]=useState(n?.title||''),[body,setBody]=useState(n?.body||'');const save=()=>{if(!title.trim()||!body.trim()){Alert.alert('제목과 내용을 입력해 주세요');return;}run(s=>{const next=policy.clone(s),now=new Date().toISOString();if(n)Object.assign(next.notices.find(x=>x.id===n.id),{title:title.trim(),body:body.trim(),updatedAt:now});else{next.notices.unshift({id:policy.id('notice'),title:title.trim(),body:body.trim(),createdAt:now,updatedAt:now});next.users.filter(u=>u.role==='student'&&u.approval==='approved').forEach(u=>policy.notify(next,u.id,title.trim(),body.trim(),'NOTICE'));}policy.audit(next,n?'NOTICE_EDIT':'NOTICE_ADD',title,currentUser.id);return next});navigation.goBack()};return <Screen><Field label="제목" value={title} onChangeText={setTitle}/><Field label="내용" value={body} onChangeText={setBody} multiline/><Button title="저장" onPress={save}/>{n?<Button title="알림 삭제" kind="danger" onPress={()=>confirm('알림 삭제',n.title,()=>{run(s=>({...s,notices:s.notices.filter(x=>x.id!==n.id)}));navigation.goBack()})}/>:null}</Screen>}
export function AdminStatsScreen(){const{state,policy}=useApp();const statuses=['RESERVED','RENTING','RETURNED','CANCELLED','NO_SHOW'];const max=Math.max(1,...statuses.map(x=>state.bookings.filter(b=>b.status===x).length));return <Screen><Lead>현재 로컬 기록에서 계산됩니다.</Lead><Section title="대여 상태별 건수"><Card>{statuses.map(x=>{const n=state.bookings.filter(b=>b.status===x).length;return <View key={x} style={s.statRow}><Text style={s.statLabel}>{statusLabel[x]}</Text><View style={s.statTrack}><View style={[s.statBar,{width:`${Math.max(n?5:0,n/max*100)}%`}]}/></View><Text style={s.statNumber}>{n}</Text></View>})}</Card></Section><Section title="운영 요약"><Card>{[['전체 모델',state.models.length],['정상 기기',state.models.reduce((a,m)=>a+m.units.filter(u=>u.condition==='NORMAL').length,0)],['학생증 승인 대기',state.users.filter(u=>u.approval==='pending').length],['답변 대기 문의',state.inquiries.filter(x=>!x.response).length],['답변 대기 구매 요청',state.purchases.filter(x=>!x.response).length],['유효 경고',state.users.reduce((n,u)=>n+policy.activeWarnings(state,u.id).length,0)]].map(([k,n])=><View key={k} style={s.statRow}><Text style={s.statLabel}>{k}</Text><Text style={s.statNumber}>{n}</Text></View>)}</Card></Section></Screen>}
export function AdminRequestsScreen({route}){const{state,currentUser,run,policy}=useApp();const[type,setType]=useState(route?.params?.type||'inquiries'),[responses,setResponses]=useState({});const records=state[type];const answer=x=>{if(!responses[x.id]?.trim()){Alert.alert('답변을 입력해 주세요');return;}run(s=>{const n=policy.clone(s),item=n[type].find(y=>y.id===x.id);item.response=responses[x.id].trim();item.respondedAt=new Date().toISOString();policy.notify(n,x.userId,'관리자 답변 등록',item.title,'RESPONSE',x.id);return n});Alert.alert('답변 등록 완료','학생에게 알림을 보냈습니다.')};return <Screen><View style={s.row}><Button title="문의" kind={type==='inquiries'?'primary':'secondary'} style={s.half} onPress={()=>setType('inquiries')}/><Button title="구매 요청" kind={type==='purchases'?'primary':'secondary'} style={s.half} onPress={()=>setType('purchases')}/></View><View style={s.rowList}>{records.length?records.map(x=><Card key={x.id} style={s.card}><Text style={s.heading}>{x.title}</Text><Text style={s.meta}>{state.users.find(u=>u.id===x.userId)?.name||'탈퇴 회원'} · {formatDate(x.createdAt)}</Text><Text style={s.body}>{x.body}</Text>{x.response?<Banner text={`답변: ${x.response}`}/>:<><Field label="답변" value={responses[x.id]||''} onChangeText={v=>setResponses(p=>({...p,[x.id]:v}))} multiline/><Button title="답변 등록" onPress={()=>answer(x)}/></>}</Card>):<Empty title="접수된 요청이 없습니다"/>}</View></Screen>}
