export function AdminReturnLookup({route,navigation}){const{state,policy}=useApp();const[code,setCode]=useState(''),[scanning,setScanning]=useState(false);const pickup=route.params?.mode==='pickup';
  useEffect(()=>{navigation.setOptions({title:pickup?'수령 처리':'반납 처리'})},[navigation,pickup]);
  const open=value=>{const v=String(value).trim();if(!v){Alert.alert(pickup?'기기 고유 번호나 학번을 입력해 주세요':'기기 고유 번호를 입력해 주세요');return;}
    const b=pickup
      ? state.bookings.find(x=>['RESERVED','WAITING'].includes(x.status)&&(x.unitId===v||state.users.find(u=>u.id===x.userId)?.studentNumber===v))
      : state.bookings.find(x=>policy.HELD.includes(x.status)&&x.unitId===v);
    if(!b){Alert.alert(pickup?'수령할 예약을 찾을 수 없습니다':'대여 중 기기를 찾을 수 없습니다',pickup?'기기 고유 번호나 학번을 확인해 주세요.':'기기 고유 번호와 현재 보유 상태를 확인해 주세요.');return;}
    setCode('');navigation.navigate('AdminHandoff',pickup?{bookingId:b.id}:{bookingId:b.id,code:v});}; // 반납은 찾을 때 쓴 번호를 그대로 넘겨 다시 입력하지 않게 한다
  return <Screen><Banner text={pickup?'예약한 학생이 오면 기기를 찍거나 학번으로 찾아 수령 처리합니다.':'학생이 기기를 들고 오면 찍거나 고유 번호로 찾아 반납 처리합니다.'}/>
    <ScanSheet visible={scanning} onClose={()=>setScanning(false)} onScanned={v=>{setScanning(false);open(v)}} title={pickup?'수령 기기 스캔':'반납 기기 스캔'}/>
    <Section title="QR·바코드로 찾기"><Card style={s.scanCard}><View style={s.modeIcon}><Ionicons name="qr-code-outline" size={30} color={c.primary}/></View><Text style={s.modeTitle}>기기에 붙은 코드를 비추세요</Text><Text style={s.modeText}>코드를 읽으면 해당 예약으로 바로 이동합니다.</Text></Card><Button title="카메라 열기" icon="qr-code-outline" onPress={()=>setScanning(true)}/></Section>
    <Section title={pickup?'고유 번호나 학번으로 찾기':'고유 번호로 찾기'}><Field label={pickup?'기기 고유 번호 또는 학번':'기기 고유 번호'} value={code} onChangeText={setCode} placeholder={pickup?'기기에 붙은 번호 또는 학번':'기기에 붙은 고유 번호'}/><Button title="예약 찾기" onPress={()=>open(code)}/></Section>
  </Screen>}
export function AdminReturnCorrection({route,navigation}){const{state,currentUser,run,policy}=useApp();const b=state.bookings.find(x=>x.id===route.params?.bookingId);const[date,setDate]=useState(null),[time,setTime]=useState(null);if(!b)return <Screen><Empty title="기록이 없습니다"/></Screen>;const model=state.models.find(m=>m.id===b.modelId);
  const picked=new Date(b.pickedAt||b.start);const today=new Date();const range=date?{open:Math.max(policy.openFor(state,model,date).getTime(),picked.getTime()),close:Math.min(policy.closeFor(state,model,date).getTime(),today.getTime())}:null; // 고른 날의 운영 시간 안에서, 수령 이후·지금 이전만 고른다
  const submit=()=>{try{const next=policy.correctReturn(state,b.id,currentUser.id,new Date(time));run(()=>next);Alert.alert('정정 완료','실제 반납 시간과 연체 경고가 다시 계산되었습니다.');navigation.goBack()}catch(e){Alert.alert('정정할 수 없습니다',e.message)}};
  return <Screen><Banner text="실제 반납 시각을 고르세요. 연체 경고를 다시 계산하고 관리 기록에 남깁니다."/><Text style={s.meta}>기록된 반납: {formatDate(b.returnedAt)}</Text><DateField label="실제 반납 날짜" value={date} onChange={d=>{setDate(d);setTime(null)}} min={picked} max={today} blocked={d=>policy.closedDay(state,d)}/>{date&&!(range&&range.open<=range.close)?<Text style={s.meta}>이 날은 고를 수 있는 시간이 없습니다.</Text>:<ClockField label="실제 반납 시각" value={time} onChange={setTime} min={range?.open} max={range?.close} disabled={!date} placeholder={date?'운영 시간 안에서 5분 단위':'날짜를 먼저 고르세요'}/>}<Button title="정정 저장" disabled={!time} onPress={submit}/></Screen>}
